<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { NodeMetadata } from '../types'
import type { AlertEvent, AlertKind, AlertRule, NotificationChannel, NotificationTemplate } from '../admin-api'
import { createAlertRule, createChannel, createNotificationTemplate, deleteAlertRule, deleteChannel, deleteNotificationTemplate, loadAlertEvents, loadAlertRules, loadChannels, loadNotificationTemplates, testChannel, testNotificationTemplate, updateAlertRule, updateChannel, updateNotificationTemplate } from '../admin-api'
import { DsBadge, DsButton, DsEmptyState, DsStatusIndicator, DsTabs } from '../design-system'

const props = defineProps<{ nodes: NodeMetadata[] }>()
const emit = defineEmits<{ notice: [value: string]; error: [value: unknown] }>()
type View = 'overview' | 'channels' | 'rules' | 'templates' | 'history'
const view = ref<View>('overview')
const busy = ref(false)
const channels = ref<NotificationChannel[]>([])
const rules = ref<AlertRule[]>([])
const templates = ref<NotificationTemplate[]>([])
const events = ref<AlertEvent[]>([])
const historyState = ref('all')
const historyProvider = ref('all')

const channelForm = reactive({ id:'', name:'', kind:'webhook' as NotificationChannel['kind'], enabled:true, url:'', method:'POST', headers:'', body_template:'', bot_token:'', chat_id:'', thread_id:'', parse_mode:'', smtp_host:'', smtp_port:587, smtp_username:'', smtp_password:'', smtp_from:'', smtp_to:'', smtp_encryption:'starttls' })
const ruleForm = reactive({ id:'', node_id:'', channel_id:'', kind:'offline' as AlertKind, threshold:60, duration_seconds:0, cooldown_seconds:900, repeat_seconds:900, template_id:'', enabled:true })
const templateForm = reactive({ id:'', name:'', event_kind:'firing', title_template:'MyProbe 告警 · {{node.name}}', body_template:'{{message}}' })
const tabs = [{value:'overview',label:'概览'},{value:'channels',label:'通知通道'},{value:'rules',label:'告警规则'},{value:'templates',label:'消息模板'},{value:'history',label:'发送历史'}]
const templateVariables = ['{{node.name}}','{{message}}','{{state}}','{{event}}']
const healthyChannels = computed(() => channels.value.filter(x=>x.enabled && x.last_test_status==='success').length)
const firingEvents = computed(() => events.value.filter(x=>x.state==='firing').length)
const failedEvents = computed(() => events.value.filter(x=>x.state==='failed').length)
const filteredEvents = computed(() => events.value.filter(x => (historyState.value==='all'||x.state===historyState.value) && (historyProvider.value==='all'||x.provider===historyProvider.value)))

async function refresh(){ const [c,r,t,e]=await Promise.all([loadChannels(),loadAlertRules(),loadNotificationTemplates(),loadAlertEvents()]);channels.value=c.channels;rules.value=r.rules;templates.value=t.templates;events.value=e.events }
async function run(action:()=>Promise<void>,message=''){busy.value=true;try{await action();if(message)emit('notice',message)}catch(e){emit('error',e)}finally{busy.value=false}}
function resetChannel(){Object.assign(channelForm,{id:'',name:'',kind:'webhook',enabled:true,url:'',method:'POST',headers:'',body_template:'',bot_token:'',chat_id:'',thread_id:'',parse_mode:'',smtp_host:'',smtp_port:587,smtp_username:'',smtp_password:'',smtp_from:'',smtp_to:'',smtp_encryption:'starttls'})}
function editChannel(item?:NotificationChannel){resetChannel();if(item)Object.assign(channelForm,{id:item.id,name:item.name,kind:item.kind,enabled:item.enabled})}
function channelConfig(){let headers:Record<string,string>={};if(channelForm.headers.trim()){for(const line of channelForm.headers.split('\n')){const at=line.indexOf(':');if(at>0)headers[line.slice(0,at).trim()]=line.slice(at+1).trim()}}return {url:channelForm.url,method:channelForm.method,headers,body_template:channelForm.body_template,bot_token:channelForm.bot_token,chat_id:channelForm.chat_id,thread_id:channelForm.thread_id,parse_mode:channelForm.parse_mode,smtp_host:channelForm.smtp_host,smtp_port:channelForm.smtp_port,smtp_username:channelForm.smtp_username,smtp_password:channelForm.smtp_password,smtp_from:channelForm.smtp_from,smtp_to:channelForm.smtp_to,smtp_encryption:channelForm.smtp_port===465?'tls':channelForm.smtp_encryption}}
async function saveChannel(){await run(async()=>{const config=channelConfig();if(channelForm.id){const hasCredentials=Object.values(config).some(v=>typeof v==='string'&&v.trim()!==''&&v!=='POST'&&v!=='starttls')||channelForm.smtp_port!==587;await updateChannel(channelForm.id,{name:channelForm.name,kind:channelForm.kind,enabled:channelForm.enabled,...(hasCredentials?{config}:{})})}else await createChannel({name:channelForm.name,kind:channelForm.kind,config});resetChannel();await refresh()},'通知通道已保存。')}
async function removeChannel(item:NotificationChannel){if(!confirm(`删除通知通道“${item.name}”？关联规则也会被删除。`))return;await run(async()=>{await deleteChannel(item.id);await refresh()},'通知通道已删除。')}
async function sendTest(item:NotificationChannel){await run(async()=>{await testChannel(item.id);await refresh()},'测试消息已发送。')}
function resetRule(){Object.assign(ruleForm,{id:'',node_id:'',channel_id:'',kind:'offline',threshold:60,duration_seconds:0,cooldown_seconds:900,repeat_seconds:900,template_id:'',enabled:true})}
function editRule(item?:AlertRule){resetRule();if(!item)return;const value=item.config.offline_seconds??item.config.threshold_percent??item.config.threshold_milliseconds??item.config.threshold_bytes_per_second??item.config.threshold_bytes??item.config.days_before??0;Object.assign(ruleForm,{id:item.id,node_id:item.node_id,channel_id:item.channel_id,kind:item.kind,threshold:value,duration_seconds:item.config.duration_seconds??0,repeat_seconds:item.config.repeat_seconds??item.cooldown_seconds,template_id:item.config.template_id??'',cooldown_seconds:item.cooldown_seconds,enabled:item.enabled})}
function ruleConfig(){const config:Record<string,unknown>={duration_seconds:ruleForm.duration_seconds,repeat_seconds:ruleForm.repeat_seconds,template_id:ruleForm.template_id};config[ruleForm.kind==='offline'?'offline_seconds':['cpu','memory','disk'].includes(ruleForm.kind)?'threshold_percent':ruleForm.kind==='latency'?'threshold_milliseconds':ruleForm.kind==='bandwidth'?'threshold_bytes_per_second':ruleForm.kind==='cycle_traffic'?'threshold_bytes':'days_before']=ruleForm.threshold;return config}
async function saveRule(){await run(async()=>{const payload={node_id:ruleForm.node_id,channel_id:ruleForm.channel_id,kind:ruleForm.kind,config:ruleConfig(),cooldown_seconds:ruleForm.cooldown_seconds,enabled:ruleForm.enabled};if(ruleForm.id)await updateAlertRule(ruleForm.id,payload);else await createAlertRule(payload);resetRule();await refresh()},'告警规则已保存。')}
async function removeRule(item:AlertRule){if(!confirm('删除这条告警规则？'))return;await run(async()=>{await deleteAlertRule(item.id);await refresh()},'告警规则已删除。')}
function resetTemplate(){Object.assign(templateForm,{id:'',name:'',event_kind:'firing',title_template:'MyProbe 告警 · {{node.name}}',body_template:'{{message}}'})}
function editTemplate(item?:NotificationTemplate){resetTemplate();if(item)Object.assign(templateForm,item)}
async function saveTemplate(){await run(async()=>{const payload={...templateForm};if(templateForm.id)await updateNotificationTemplate(templateForm.id,payload);else await createNotificationTemplate(payload);resetTemplate();await refresh()},'消息模板已保存。')}
async function removeTemplate(item:NotificationTemplate){if(item.is_default||!confirm(`删除模板“${item.name}”？`))return;await run(async()=>{await deleteNotificationTemplate(item.id);await refresh()},'消息模板已删除。')}
async function sendTemplateTest(item:NotificationTemplate){const channel=channels.value.find(x=>x.enabled);if(!channel){emit('error',new Error('请先启用至少一个通知通道。'));return};await run(async()=>{await testNotificationTemplate(item.id,channel.id);await refresh()},`模板测试已发送到“${channel.name}”。`)}
const nodeName=(id:string)=>props.nodes.find(x=>x.id===id)?.name||'未知节点'
const channelName=(id:string)=>channels.value.find(x=>x.id===id)?.name||'未知通道'
const kindName=(kind:AlertKind)=>({offline:'离线',cpu:'CPU 过高',memory:'内存过高',disk:'磁盘过高',latency:'延迟异常',bandwidth:'带宽超限',cycle_traffic:'周期流量',expiry:'即将到期'}[kind])
const thresholdLabel=(kind:AlertKind)=>kind==='offline'?'离线判定（秒）':['cpu','memory','disk'].includes(kind)?'阈值（%）':kind==='latency'?'延迟阈值（ms）':kind==='expiry'?'提前提醒（天）':kind==='bandwidth'?'阈值（B/s）':'阈值（B）'
const providerName=(kind:string)=>({webhook:'Webhook',telegram:'Telegram',discord:'Discord',smtp:'Email / SMTP'}[kind]||kind)
const previewTitle=(value:string)=>value.replaceAll('{{node.name}}','HostDZire-SFO')
const previewBody=(value:string)=>value.replaceAll('{{message}}','CPU 使用率达到 92%，已超过阈值。')
onMounted(()=>run(refresh))
</script>

<template>
  <section class="notification-center">
    <header class="notification-hero"><div><span class="eyebrow">NOTIFICATION SYSTEM</span><h1>通知中心</h1><p>统一管理告警触发、发送通道、消息模板与交付记录。</p></div><div class="notification-health"><span class="health-dot"></span><div><strong>通知引擎运行中</strong><small>状态去重与恢复通知已启用</small></div></div></header>
    <DsTabs v-model="view" :items="tabs" label="通知中心导航" />

    <template v-if="view==='overview'">
      <section class="notification-stats"><article><span>已启用通道</span><strong>{{ channels.filter(x=>x.enabled).length }}</strong><small>{{ healthyChannels }} 个测试正常</small></article><article><span>监控规则</span><strong>{{ rules.filter(x=>x.enabled).length }}</strong><small>持久化去重与冷却</small></article><article><span>近期告警</span><strong>{{ firingEvents }}</strong><small>包含恢复事件</small></article><article :class="{warn:failedEvents}"><span>发送失败</span><strong>{{ failedEvents }}</strong><small>{{ failedEvents?'请检查历史记录':'所有通道运行正常' }}</small></article></section>
      <div class="notification-overview-grid"><section class="notification-card"><header><div><span class="eyebrow">CHANNEL HEALTH</span><h2>通道状态</h2></div><DsButton size="small" @click="view='channels'">管理</DsButton></header><div v-for="item in channels.slice(0,4)" :key="item.id" class="health-row"><span class="provider-icon">{{ item.kind==='telegram'?'TG':item.kind==='discord'?'DC':item.kind==='smtp'?'@':'WH' }}</span><div><strong>{{ item.name }}</strong><small>{{ providerName(item.kind) }} · {{ item.last_test_at?new Date(item.last_test_at).toLocaleString('zh-CN',{hour12:false}):'尚未测试' }}</small></div><DsStatusIndicator :status="!item.enabled?'neutral':item.last_test_status==='failed'?'offline':item.last_test_status==='success'?'online':'warning'" :label="!item.enabled?'停用':item.last_test_status==='failed'?'失败':item.last_test_status==='success'?'正常':'待测试'" /></div><DsEmptyState v-if="!channels.length" title="尚未添加通道" description="先连接一个 Webhook、Telegram、Discord 或 SMTP 通道。" /></section>
      <section class="notification-card"><header><div><span class="eyebrow">RECENT DELIVERY</span><h2>最近发送</h2></div><DsButton size="small" @click="view='history'">查看全部</DsButton></header><div v-for="item in events.slice(0,5)" :key="item.id" class="delivery-row"><DsBadge :tone="item.state==='failed'?'danger':item.state==='resolved'?'success':'warning'">{{ item.state==='failed'?'失败':item.state==='resolved'?'恢复':'告警' }}</DsBadge><div><strong>{{ nodeName(item.node_id||'') }}</strong><small>{{ item.channel_name||'通知通道' }} · {{ new Date(item.created_at).toLocaleString('zh-CN',{hour12:false}) }}</small></div></div><DsEmptyState v-if="!events.length" title="暂无发送记录" description="告警触发或通道测试后，记录会出现在这里。" /></section></div>
    </template>

    <template v-else-if="view==='channels'">
      <div class="notification-workspace"><form class="notification-card editor" @submit.prevent="saveChannel"><span class="eyebrow">PROVIDER</span><h2>{{ channelForm.id?'编辑通知通道':'添加通知通道' }}</h2><p>凭据使用服务端 AES-GCM 加密，API 不会返回明文。</p><div class="form-grid two"><label>通道名称<input v-model="channelForm.name" required placeholder="生产告警"></label><label>Provider<select v-model="channelForm.kind"><option value="webhook">Webhook</option><option value="telegram">Telegram</option><option value="discord">Discord</option><option value="smtp">Email / SMTP</option></select></label></div><template v-if="channelForm.kind==='webhook'"><label>Endpoint URL<input v-model="channelForm.url" type="url" :required="!channelForm.id" placeholder="https://example.com/hooks/myprobe"></label><div class="form-grid two"><label>Method<select v-model="channelForm.method"><option>POST</option><option>PUT</option><option>PATCH</option></select></label><label>自定义 Headers<textarea v-model="channelForm.headers" rows="2" placeholder="Authorization: Bearer …"></textarea></label></div><label>Body 模板（可选）<textarea v-model="channelForm.body_template" rows="3" placeholder='{"title":"{{title}}","message":"{{message}}"}'></textarea></label></template><template v-else-if="channelForm.kind==='telegram'"><label>Bot Token<input v-model="channelForm.bot_token" type="password" :required="!channelForm.id" autocomplete="new-password"></label><div class="form-grid two"><label>Chat ID<input v-model="channelForm.chat_id" :required="!channelForm.id"></label><label>Thread ID<input v-model="channelForm.thread_id"></label><label>Parse Mode<select v-model="channelForm.parse_mode"><option value="">纯文本</option><option>HTML</option><option>MarkdownV2</option></select></label></div></template><template v-else-if="channelForm.kind==='discord'"><label>Discord Webhook URL<input v-model="channelForm.url" type="password" :required="!channelForm.id" autocomplete="new-password"></label></template><template v-else><div class="form-grid two"><label>SMTP Host<input v-model="channelForm.smtp_host" :required="!channelForm.id"></label><label>端口<input v-model.number="channelForm.smtp_port" type="number" min="1" max="65535"></label><label>用户名<input v-model="channelForm.smtp_username" autocomplete="off"></label><label>密码<input v-model="channelForm.smtp_password" type="password" :required="!channelForm.id" autocomplete="new-password"></label><label>发件人<input v-model="channelForm.smtp_from" type="email" :required="!channelForm.id"></label><label>收件人<input v-model="channelForm.smtp_to" type="email" :required="!channelForm.id"></label></div><p class="security-note">当前仅允许 STARTTLS，避免明文 SMTP 凭据传输。</p></template><label v-if="channelForm.id" class="toggle-row"><input v-model="channelForm.enabled" type="checkbox">启用此通道</label><footer><DsButton variant="primary" :disabled="busy">{{ channelForm.id?'保存修改':'创建通道' }}</DsButton><DsButton v-if="channelForm.id" type="button" @click="editChannel()">取消</DsButton></footer></form>
      <section class="channel-list"><article v-for="item in channels" :key="item.id" class="notification-card channel-item"><header><span class="provider-icon large">{{ item.kind==='telegram'?'TG':item.kind==='discord'?'DC':item.kind==='smtp'?'@':'WH' }}</span><div><h3>{{ item.name }}</h3><p>{{ providerName(item.kind) }}</p></div><DsStatusIndicator :status="item.enabled?'online':'neutral'" :label="item.enabled?'已启用':'已停用'" /></header><div class="channel-test"><span>最近测试</span><strong :class="item.last_test_status">{{ item.last_test_status==='success'?'发送成功':item.last_test_status==='failed'?'发送失败':'尚未测试' }}</strong><small>{{ item.last_test_error|| (item.last_test_at?new Date(item.last_test_at).toLocaleString('zh-CN',{hour12:false}):'—') }}</small></div><footer><DsButton size="small" @click="sendTest(item)">发送测试</DsButton><DsButton size="small" @click="editChannel(item)">编辑</DsButton><DsButton size="small" variant="danger" @click="removeChannel(item)">删除</DsButton></footer></article><DsEmptyState v-if="!channels.length" title="还没有通知通道" description="添加一个 Provider，开始接收 MyProbe 告警。" /></section></div>
    </template>

    <template v-else-if="view==='rules'">
      <div class="notification-workspace"><form class="notification-card editor" @submit.prevent="saveRule"><span class="eyebrow">ALERT POLICY</span><h2>{{ ruleForm.id?'编辑告警规则':'创建告警规则' }}</h2><div class="form-grid two"><label>节点<select v-model="ruleForm.node_id" required><option value="" disabled>选择节点</option><option v-for="n in nodes" :key="n.id" :value="n.id">{{ n.name }}</option></select></label><label>通知通道<select v-model="ruleForm.channel_id" required><option value="" disabled>选择通道</option><option v-for="c in channels.filter(x=>x.enabled)" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>事件类型<select v-model="ruleForm.kind"><option value="offline">离线 / 恢复</option><option value="cpu">CPU 过高</option><option value="memory">内存过高</option><option value="disk">磁盘过高</option><option value="latency">延迟异常</option><option value="bandwidth">带宽超限</option><option value="cycle_traffic">周期流量</option><option value="expiry">即将到期</option></select></label><label>{{ thresholdLabel(ruleForm.kind) }}<input v-model.number="ruleForm.threshold" type="number" min="0" step="any" required></label><label>持续时间（秒）<input v-model.number="ruleForm.duration_seconds" type="number" min="0"><small>状态持续多久后触发，0 为立即</small></label><label>重复提醒（秒）<input v-model.number="ruleForm.repeat_seconds" type="number" min="30"><small>告警持续时的再次提醒间隔</small></label><label>冷却时间（秒）<input v-model.number="ruleForm.cooldown_seconds" type="number" min="30" max="2592000"></label><label>消息模板<select v-model="ruleForm.template_id"><option value="">系统默认</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.name }}</option></select></label></div><label v-if="ruleForm.id" class="toggle-row"><input v-model="ruleForm.enabled" type="checkbox">启用此规则</label><footer><DsButton variant="primary" :disabled="busy||!nodes.length||!channels.length">{{ ruleForm.id?'保存修改':'创建规则' }}</DsButton><DsButton v-if="ruleForm.id" type="button" @click="editRule()">取消</DsButton></footer></form><section class="rule-list"><article v-for="item in rules" :key="item.id" class="notification-card rule-item"><header><div><h3>{{ kindName(item.kind) }}</h3><p>{{ nodeName(item.node_id) }} → {{ channelName(item.channel_id) }}</p></div><DsStatusIndicator :status="item.enabled?'online':'neutral'" :label="item.enabled?'监控中':'已停用'" /></header><dl><div><dt>持续</dt><dd>{{ item.config.duration_seconds||0 }} 秒</dd></div><div><dt>重复</dt><dd>{{ item.config.repeat_seconds||item.cooldown_seconds }} 秒</dd></div><div><dt>恢复</dt><dd>自动通知</dd></div></dl><footer><DsButton size="small" @click="editRule(item)">编辑</DsButton><DsButton size="small" variant="danger" @click="removeRule(item)">删除</DsButton></footer></article><DsEmptyState v-if="!rules.length" title="尚未配置规则" description="创建规则后，告警状态会跨重启持久化。" /></section></div>
    </template>

    <template v-else-if="view==='templates'">
      <div class="notification-workspace"><form class="notification-card editor" @submit.prevent="saveTemplate"><span class="eyebrow">SAFE TEMPLATE</span><h2>{{ templateForm.id?'编辑消息模板':'创建消息模板' }}</h2><p>仅支持白名单变量，不执行脚本、表达式或 HTML。</p><label>模板名称<input v-model="templateForm.name" required></label><label>适用状态<select v-model="templateForm.event_kind"><option value="firing">告警</option><option value="resolved">恢复</option><option value="all">全部</option></select></label><label>标题模板<input v-model="templateForm.title_template" required maxlength="300"></label><label>正文模板<textarea v-model="templateForm.body_template" required rows="7" maxlength="8000"></textarea></label><div class="variable-list"><code v-for="variable in templateVariables" :key="variable">{{ variable }}</code></div><footer><DsButton variant="primary" :disabled="busy">{{ templateForm.id?'保存修改':'创建模板' }}</DsButton><DsButton v-if="templateForm.id" type="button" @click="editTemplate()">取消</DsButton></footer></form><section class="template-list"><article v-for="item in templates" :key="item.id" class="notification-card template-item"><header><div><h3>{{ item.name }}</h3><p>{{ item.event_kind==='firing'?'告警':item.event_kind==='resolved'?'恢复':'全部事件' }}</p></div><DsBadge v-if="item.is_default">系统默认</DsBadge></header><div class="template-preview"><strong>{{ previewTitle(item.title_template) }}</strong><p>{{ previewBody(item.body_template) }}</p></div><footer><DsButton size="small" @click="editTemplate({...item,id:'' ,name:item.name+' 副本',is_default:false})">复制</DsButton><DsButton v-if="!item.is_default" size="small" @click="editTemplate(item)">编辑</DsButton><DsButton v-if="!item.is_default" size="small" variant="danger" @click="removeTemplate(item)">删除</DsButton></footer></article></section></div>
    </template>

    <template v-else><section class="notification-card history-card"><header><div><span class="eyebrow">DELIVERY LOG</span><h2>发送历史</h2></div><div class="history-filters"><select v-model="historyState" aria-label="按结果筛选"><option value="all">全部结果</option><option value="firing">告警</option><option value="resolved">恢复</option><option value="failed">失败</option></select><select v-model="historyProvider" aria-label="按 Provider 筛选"><option value="all">全部 Provider</option><option value="webhook">Webhook</option><option value="telegram">Telegram</option><option value="discord">Discord</option><option value="smtp">SMTP</option></select></div></header><div class="history-table"><div class="history-head"><span>结果</span><span>事件 / 节点</span><span>Provider</span><span>时间</span></div><article v-for="item in filteredEvents" :key="item.id"><DsBadge :tone="item.state==='failed'?'danger':item.state==='resolved'?'success':'warning'">{{ item.state==='failed'?'失败':item.state==='resolved'?'恢复':'告警' }}</DsBadge><div><strong>{{ nodeName(item.node_id||'') }}</strong><small>{{ item.delivery_error||item.message }}</small></div><div><strong>{{ item.channel_name||'—' }}</strong><small>{{ providerName(item.provider||'') }}</small></div><time>{{ new Date(item.created_at).toLocaleString('zh-CN',{hour12:false}) }}</time></article><DsEmptyState v-if="!filteredEvents.length" title="没有匹配的发送记录" description="调整筛选条件，或等待下一次告警触发。" /></div></section></template>
  </section>
</template>

<style scoped>
